hooks.command:
python3 -c 'import json,re,sys
d=json.load(sys.stdin)
t=d.get("tool_name","")
i=d.get("tool_input") or {}
S=re.compile(r"^\.(dev\.vars|env)(\.[\w.-]+)?$")
C=re.compile(r"(?:^|[\s/\x27\"=<>:(])(\.(?:dev\.vars|env)(?:\.[\w.-]+)?)(?=$|[\s\x27\";|&)<>*?\[])")
def sec(v):
    b=v.rstrip("/").rsplit("/",1)[-1]
    return (bool(S.match(b)) and not b.endswith(".example")) or bool(re.search(r"(^|/)\.(dev\.vars|env)\*?$",v))
if t=="Bash":
    hit=next((m.group(1) for m in C.finditer(i.get("command","")) if not m.group(1).endswith(".example")),None)
else:
    hit=next((v for k in ("file_path","notebook_path","path","pattern","glob") for v in [i.get(k)] if isinstance(v,str) and sec(v)),None)
if hit:
    print("Blocked: シークレットファイル ("+hit+") へのアクセスは禁止されています。読む・作成・編集・コピーはせず、ユーザーが自分で行う手順を案内してください。",file=sys.stderr)
    sys.exit(2)
'
